function premium(){return heading('Premium Features','Premium access is granted only after verified approval or a valid trial record.')+`<div class="panel-card"><h3>Premium workspace tools</h3><p>WhatsApp and Instagram configuration, expanded automation definitions, and advanced reporting.</p><span class="pill warn">External messaging not configured</span> ${btn('View subscription','nav-subscription')}</div>`}
function wirePage(page){$('pageContent').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));const wf=$('waConnectForm');if(wf)wf.onsubmit=e=>connectMeta(e,'whatsapp');const igf=$('igConnectForm');if(igf)igf.onsubmit=e=>connectMeta(e,'instagram');const mf=$('metaReplyForm');if(mf)mf.onsubmit=sendMetaReply;if(monitorTimer){clearInterval(monitorTimer);monitorTimer=null;}if(page==='Monitoring'){loadMonitoring();monitorTimer=setInterval(()=>{if(activePage==='Monitoring')loadMonitoring()},30000);}const pf=$('paymentForm');if(pf){pf.onsubmit=submitPayment;const quote=$('quotePayment');if(quote)quote.onclick=async()=>{try{const r=await api('/api/payment-quote',{packageName:pf.elements.packageName.value,couponCode:pf.elements.couponCode.value});$('paymentQuote').textContent=r.fullFree?'₹0 — redeem this coupon in Subscription; do not make a payment.':`Payable amount: ₹${r.amount} (base ₹${r.baseAmount}, discount ₹${r.discount})`;}catch(e){$('paymentQuote').textContent=e.message}};const plan=localStorage.getItem('bp-selected-plan');const map={whatsapp_monthly:'WhatsApp AI Monthly',instagram_monthly:'Instagram AI Monthly',combo_monthly:'Combo Monthly'};if(plan&&map[plan])pf.elements.packageName.value=map[plan];localStorage.removeItem('bp-selected-plan');}const cr=$('couponRedeemForm');if(cr)cr.onsubmit=submitCouponRedeem;const gr=$('grantPremiumForm');if(gr)gr.onsubmit=submitGrantPremium;const pr=$('pricingForm');if(pr)pr.onsubmit=savePricing;const tf=$('ticketForm');if(tf)tf.onsubmit=submitTicket;const of=$('onboardForm');if(of){} }
async function action(a){try{if(a.startsWith('open-conversation-')){selectedConversation=a.slice('open-conversation-'.length);return renderPage(activePage)}if(a==='add-customers'||a==='add-customer')return customerModal();if(a==='add-products'||a==='add-product')return productModal();if(a==='add-orders'||a==='add-order')return orderModal();if(a==='add-automation'){if(!premiumActive)return toast('Automation Builder requires an active Premium plan.');return automationModal()};if(a.startsWith('close-ticket-')||a.startsWith('reopen-ticket-')){const closed=a.startsWith('close-ticket-'),id=a.slice(closed?'close-ticket-'.length:'reopen-ticket-'.length);await updateDoc(doc(db,'support_tickets',id),{status:closed?'closed':'open',updatedAt:serverTimestamp()});await writeAudit('support_ticket_status_changed',{ticketId:id,status:closed?'closed':'open'});return renderPage('Support Tickets')}if(a.startsWith('revoke-premium-')){const targetId=a.slice('revoke-premium-'.length);const r=await api('/api/admin-manage',{action:'revoke_premium',targetId});toast(r.message);return renderPage('Subscriptions')}if(a.startsWith('suspend-user-')||a.startsWith('activate-user-')||a.startsWith('suspend-business-')||a.startsWith('activate-business-')){const [verb,kind,...rest]=a.split('-');const targetId=rest.join('-');const actionName=`${verb}_${kind}`;const r=await api('/api/admin-manage',{action:actionName,targetId});toast(r.message);return renderPage(kind==='user'?'Users':'Businesses')}if(a==='add-coupon')return couponModal();if(a.startsWith('edit-coupon-'))return couponModal(a.slice('edit-coupon-'.length));if(a.startsWith('toggle-coupon-')){const id=a.slice('toggle-coupon-'.length),snap=await getDoc(doc(db,'coupons',id));if(!snap.exists())return toast('Coupon not found');await updateDoc(doc(db,'coupons',id),{status:snap.data().status==='active'?'paused':'active',updatedAt:serverTimestamp()});await writeAudit('coupon_status_changed',{couponId:id});return renderPage('Coupon Manager')}if(a.startsWith('delete-coupon-')){const id=a.slice('delete-coupon-'.length);if(!confirm('Delete this coupon permanently?'))return;await deleteDoc(doc(db,'coupons',id));await writeAudit('coupon_deleted',{couponId:id});return renderPage('Coupon Manager')}if(a.startsWith('edit-Customers-'))return customerModal(a.split('-').at(-1));if(a.startsWith('edit-Products-'))return productModal(a.split('-').at(-1));if(a.startsWith('edit-Orders-'))return orderModal(a.split('-').at(-1));if(a.startsWith('archive-')){const [,p,id]=a.split('-');const name=coll[p];await api('/api/business-record',{collection:name,recordId:id,operation:'archive'});toast('Record archived');return renderPage(p)}if(a==='export-csv'||a==='export-json')return exportData(a==='export-csv'?'csv':'json');if(a==='generate-ai'){if(!premiumActive)return toast('AI Studio generation requires an active Premium plan. Activate a trial or renew Premium.');const kind=$('aiKind').value,ctx=$('aiPrompt').value,lang=$('aiLanguage').value;if(!ctx.trim())return toast('Enter business context first.');$('aiOutput').value='Generating…';try{const r=await api('/api/ai-generate',{kind,prompt:ctx,language:lang});$('aiOutput').value=r.output;toast('AI draft generated. Review facts before using it.')}catch(e){$('aiOutput').value='';toast(e.message)}return}if(a==='manual-draft'){const kind=$('aiKind').value,ctx=$('aiPrompt').value,lang=$('aiLanguage').value;$('aiOutput').value=`${kind} — ${lang}\n\n${ctx}\n\n[Review and complete this draft using verified business details.]`;return}if(a==='copy-draft')return copy($('aiOutput').value);if(a==='copy-reply')return copy($('replyDraft').value);if(a==='copy-email')return copy(`Subject: ${$('emailSubject').value}\n\n${$('emailBody').value}`);if(a.startsWith('nav-')){const map={'nav-backups':'Backups','nav-reports':'Reports','nav-subscription':'Subscription'};activePage=map[a];setNav();return renderPage(activePage)}if(a.startsWith('review-payment-'))return reviewPayment(a.split('-').at(-1));if(a==='request-payment'){activePage='Payments';setNav();return renderPage('Payments')}if(a==='activate-trial'){const r=await api('/api/trial-activate',{});toast(`Premium trial activated for ${r.trialDays} days`);await loadSubscription();return renderPage('Subscription')}toast('This action is not available in the current configuration.')}catch(e){toast(e.message)}}
function customerModal(id=null){showModal(`<h2>${id?'Edit':'Add'} customer</h2><form id="recordForm"><div class="field"><label>Name *</label><input name="name" required></div><div class="form-grid"><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Email</label><input name="email" type="email"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><button class="btn btn-primary">Save customer</button></form>`);bindRecordForm('customers',id)}
function productModal(id=null){showModal(`<h2>${id?'Edit':'Add'} product</h2><form id="recordForm"><div class="field"><label>Product name *</label><input name="name" required></div><div class="form-grid"><div class="field"><label>Category</label><input name="category"></div><div class="field"><label>Price (₹)</label><input name="price" type="number" min="0" step="0.01"></div><div class="field"><label>Stock quantity</label><input name="stock" type="number" min="0"></div><div class="field"><label>Image URL (optional)</label><input name="imageUrl" type="url"></div></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><button class="btn btn-primary">Save product</button></form>`);bindRecordForm('products',id)}
async function orderModal(id=null){const cs=await getRows('customers');showModal(`<h2>${id?'Edit':'Create'} order</h2><form id="recordForm"><div class="field"><label>Customer</label><select name="customerId"><option value="">Select customer</option>${cs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Customer name</label><input name="customerName"></div><div class="form-grid"><div class="field"><label>Total (₹)</label><input name="total" type="number" min="0" step="0.01" required></div><div class="field"><label>Payment status</label><select name="paymentStatus"><option>pending</option><option>paid</option><option>failed</option></select></div></div><div class="field"><label>Order status</label><select name="status"><option>pending</option><option>processing</option><option>completed</option><option>cancelled</option></select></div><button class="btn btn-primary">Save order</button></form>`);bindRecordForm('orders',id)}
async function bindRecordForm(name,id){const form=$('recordForm');let old={};if(id){const s=await getDoc(doc(db,name,id));old=s.data()||{};for(const [k,v] of Object.entries(old)){const el=form.elements[k];if(el&&v!=null)el.value=v}}form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form).entries());if(name==='products'||name==='orders'){for(const k of ['price','stock','total'])if(data[k]!==undefined)data[k]=Number(data[k]||0)}try{await saveBusinessRecord(name,data,id);closeModal()}catch(err){toast(err.message)}}}
function automationModal(){showModal(`<h2>New automation</h2><p class="muted">This saves a workflow definition. It does not send external messages.</p><form id="recordForm"><div class="field"><label>Name</label><input name="name" required></div><div class="form-grid"><div class="field"><label>Trigger</label><select name="trigger"><option>New customer</option><option>New enquiry</option><option>Product enquiry</option><option>Order created</option><option>Payment submitted</option><option>Follow-up reminder</option></select></div><div class="field"><label>Action</label><select name="action"><option>Create reply draft</option><option>Create internal notification</option><option>Flag for human review</option></select></div></div><div class="field"><label>Reply template / instructions</label><textarea name="template"></textarea></div><div class="field"><label>Enabled</label><select name="enabled"><option value="false">Disabled (safe default)</option><option value="true">Enabled for local test mode only</option></select></div><button class="btn btn-primary">Save workflow</button></form>`);$('recordForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());d.enabled=d.enabled==='true';try{await saveBusinessRecord('automations',d);closeModal()}catch(err){toast(err.message)}}}
async function couponModal(id=null){let old={};if(id){const snap=await getDoc(doc(db,'coupons',id));if(!snap.exists())return toast('Coupon not found');old=snap.data()}showModal(`<h2>${id?'Edit':'Create'} coupon</h2><form id="recordForm"><div class="field"><label>Coupon code</label><input name="code" value="${esc(old.code||'')}" required></div><div class="form-grid"><div class="field"><label>Discount type</label><select name="type"><option value="percent" ${old.type==='percent'?'selected':''}>Percentage</option><option value="fixed" ${old.type==='fixed'?'selected':''}>Fixed amount</option></select></div><div class="field"><label>Value (100% = free)</label><input name="value" type="number" min="1" value="${esc(old.value??'')}" required></div><div class="field"><label>Expiry date</label><input name="expiry" type="date" value="${esc(old.expiry||'')}"></div><div class="field"><label>Maximum redemptions</label><input name="maxRedemptions" type="number" min="1" value="${esc(old.maxRedemptions||'')}"></div><div class="field"><label>Premium benefit days (100% coupon)</label><input name="benefitDays" type="number" min="1" max="365" value="${esc(old.benefitDays||30)}"></div></div><div class="field"><label>Restrict to user email (optional)</label><input name="restrictedEmail" type="email" value="${esc(old.restrictedEmail||'')}"></div><div class="field"><label>Status</label><select name="status"><option value="paused" ${old.status==='paused'?'selected':''}>Paused</option><option value="active" ${!old.status||old.status==='active'?'selected':''}>Active</option></select></div><button class="btn btn-primary">Save coupon</button></form>`);$('recordForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());d.code=d.code.trim().toUpperCase();if(!/^[A-Z0-9_-]{3,32}$/.test(d.code))return toast('Coupon codes must be 3–32 letters, numbers, underscores or hyphens.');d.value=Number(d.value);d.maxRedemptions=d.maxRedemptions?Number(d.maxRedemptions):null;d.benefitDays=Number(d.benefitDays||30);try{const dup=await getDocs(query(collection(db,'coupons'),where('code','==',d.code)));if(dup.docs.some(x=>x.id!==id))return toast('A coupon with this code already exists.');if(id)await updateDoc(doc(db,'coupons',id),{...d,updatedAt:serverTimestamp(),updatedBy:currentUser.uid});else await addDoc(collection(db,'coupons'),{...d,redemptionCount:0,createdAt:serverTimestamp(),createdBy:currentUser.uid});await writeAudit(id?'coupon_updated':'coupon_created',{code:d.code});closeModal();toast('Coupon saved');renderPage('Coupon Manager')}catch(err){toast(err.message)}}}
async function submitGrantPremium(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{const r=await api('/api/admin-manage',{...d,action:'grant_premium',durationDays:Number(d.durationDays)});toast(r.message);renderPage('Subscriptions')}catch(err){toast(err.message)}}
async function submitCouponRedeem(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{const r=await api('/api/coupon-redeem',d);toast(`Coupon redeemed. Premium active for ${r.benefitDays} days.`);await loadSubscription();renderPage('Subscription')}catch(err){toast(err.message)}}
async function savePricing(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries());const prices={whatsapp:{},instagram:{},combined:{}};for(const k of Object.keys(prices))for(const t of ['monthly','quarterly','yearly'])prices[k][t]=Number(f[`${k}_${t}`]);const payment={upiId:f.upiId,upiName:f.upiName,instructions:f.upiInstructions};const freeLimits={customers:Number(f.limitCustomers),products:Number(f.limitProducts),orders:Number(f.limitOrders)};try{await api('/api/platform-config',{prices,trialDays:Number(f.trialDays),payment,freeLimits});toast('Platform pricing saved securely');renderPage('Pricing Manager')}catch(err){toast(err.message)}}
async function submitPayment(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{const result=await api('/api/payment-submit',d);toast(`Payment request submitted. Payable amount: ₹${result.amount}`);renderPage('Payments')}catch(err){toast(err.message)}}
async function reviewPayment(id){const rows=await getRows('payment_requests');const p=rows.find(x=>x.id===id);if(!p)return toast('Payment request not found');showModal(`<h2>Review payment request</h2><p class="muted">${esc(p.userEmail)} · ${esc(p.packageName)} · ₹${esc(p.amount)}</p><p>Reference: <b>${esc(p.utr)}</b></p><div class="field"><label>Internal review note</label><textarea id="reviewNote" placeholder="Record how the account holder confirmed bank credit"></textarea></div><label style="display:flex;gap:9px;align-items:center;font-size:11px;color:#ddd8ee;margin:12px 0"><input type="checkbox" id="bankCreditVerified"> I confirm the account holder independently verified the actual bank credit.</label><div class="toolbar"><button class="btn btn-primary" id="approvePay">Approve after bank verification</button><button class="btn btn-outline" id="rejectPay">Reject</button></div><p class="muted-note">Only approve after the account holder independently confirms actual bank credit. A screenshot or UTR alone is insufficient.</p>`);$('approvePay').onclick=async()=>{try{await api('/api/payment-review',{paymentId:id,decision:'approve',note:$('reviewNote').value,bankCreditVerified:$('bankCreditVerified').checked});closeModal();toast('Payment approved and subscription updated');renderPage('Payment Requests')}catch(e){toast(e.message)}};$('rejectPay').onclick=async()=>{try{await api('/api/payment-review',{paymentId:id,decision:'reject',note:$('reviewNote').value});closeModal();toast('Payment request rejected');renderPage('Payment Requests')}catch(e){toast(e.message)}}}
async function submitTicket(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{await addDoc(collection(db,'support_tickets'),{...d,businessId,userUid:currentUser.uid,status:'open',createdAt:serverTimestamp()});toast('Support ticket created');renderPage(isAdmin?'Support Tickets':'Support')}catch(err){toast(err.message)}}
async function exportData(fmt){const names=['customers','products','orders'];const all={};for(const n of names)all[n]=await getRows(n);if(fmt==='json')return download('businesspilot-export.json',JSON.stringify(all,null,2),'application/json');const rows=[['collection','id','name','email','phone','price','stock','total','status']];for(const [n,items] of Object.entries(all))for(const x of items)rows.push([n,x.id,x.name||x.customerName||'',x.email||'',x.phone||'',x.price??'',x.stock??'',x.total??'',x.status||'']);download('businesspilot-export.csv',rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv')}
function download(name,content,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);toast('Export prepared')}
async function connectMeta(e,channel){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{const r=await api('/api/meta-config',{businessId,channel,...d});toast(`${channel==='whatsapp'?'WhatsApp':'Instagram'} verified and connected`);renderPage('Connected Accounts')}catch(err){toast(err.message)}}
async function sendMetaReply(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/meta-send',{businessId,...d});toast('Message sent');renderPage(activePage)}catch(err){toast(err.message)}}
async function loadMonitoring(){const box=$('monitorLive'),events=$('monitorEvents');try{const r=await api('/api/monitoring'+(isAdmin?'':`?businessId=${encodeURIComponent(businessId||'')}`),{},'GET');box.innerHTML=`<div class="stats-grid">${r.checks.map(c=>stat(c.name,c.status==='ok'?'Healthy':c.status==='warning'?'Needs setup':'Error',`${c.latencyMs} ms · ${esc(c.detail)}`)).join('')}</div><p class="muted-note">Checked ${esc(new Date(r.checkedAt).toLocaleString())}. A successful probe verifies the listed operation only.</p>`;events.innerHTML=r.recentEvents.length?table(['Time','Level','Event','Channel','Business'],r.recentEvents.map(x=>`<tr><td>${esc(x.createdAt?new Date(x.createdAt).toLocaleString():'—')}</td><td>${esc(x.level||'info')}</td><td>${esc(x.type||'')}</td><td>${esc(x.channel||x.provider||'—')}</td><td>${esc(x.businessId||'Platform')}</td></tr>`)):'<p class="muted-note">No events recorded yet.</p>'}catch(e){box.innerHTML=`<span class="pill bad">Monitoring unavailable</span><p>${esc(e.message)}</p>`;events.textContent='Could not load system events.'}}
function copy(s){navigator.clipboard?.writeText(s||'').then(()=>toast('Copied')).catch(()=>toast('Clipboard permission unavailable'))}
async function emailStudioAction(){}
$('loginTop').onclick=$('startTop').onclick=$('heroStart').onclick=$('ctaStart').onclick=async()=>{try{await signInWithPopup(auth,provider)}catch(e){toast(e.message)}};
fetch('/api/platform-config').then(r=>r.ok?r.json():null).then(c=>{if(!c?.prices)return;const p=c.prices;const set=(id,v)=>{const el=$(id);if(el)el.innerHTML=`₹${Number(v).toLocaleString('en-IN')}<small>/ month</small>`};set('price-wa-monthly',p.whatsapp.monthly);set('price-combo-monthly',p.combined.monthly);set('price-ig-monthly',p.instagram.monthly);if($('price-wa-alt'))$('price-wa-alt').textContent=`Quarterly: ₹${p.whatsapp.quarterly} / 3 months · Yearly: ${Number(p.whatsapp.yearly)>0?'₹'+p.whatsapp.yearly:'Not configured'}`;if($('price-combo-alt'))$('price-combo-alt').textContent=`Quarterly: ₹${p.combined.quarterly} / 3 months · Yearly: ${Number(p.combined.yearly)>0?'₹'+p.combined.yearly:'Not configured'}`;if($('price-ig-alt'))$('price-ig-alt').textContent=`Quarterly: ₹${p.instagram.quarterly} / 3 months · Yearly: ${Number(p.instagram.yearly)>0?'₹'+p.instagram.yearly:'Not configured'}`}).catch(()=>{});
$('signOut').onclick=async()=>{await signOut(auth);location.reload()};$('sideToggle').onclick=()=>$('sidebar').classList.toggle('open');$('menuToggle').onclick=()=>$('sidebar').classList.toggle('open');document.querySelectorAll('.plan-select').forEach(b=>b.onclick=async()=>{localStorage.setItem('bp-selected-plan',b.dataset.plan||'combo_monthly');try{await signInWithPopup(auth,provider)}catch(e){toast(e.message)}});
onAuthStateChanged(auth,async user=>{if(!user)return;currentUser=user;try{await ensureAccount(user);if(businessId===null&&!isAdmin)return;showApp()}catch(e){toast(e.message);console.error(e)}});
